select id, store_id, sale_date, units, revenue, sum(units) over (partition by product_id, store_id order by revenue, id rows between unbounded preceding and current row) running_units, min(revenue) over (partition by product_id, store_id) product_id_min_revenue, max(units) over (partition by date_trunc('week', sale_date)) sale_date_period_max_units, rank() over (partition by store_id order by units) units_rank from store_sales;
